-- Ficha de Roger Zayas-Bazán.
--
-- La biografía de relleno era completamente genérica, sin nombrar agrupación, colaborador ni
-- hecho real: en realidad es el único integrante original de 4.40 aparte de Juan Luis Guerra.
-- second_last_name añadido (Bazán). occupations corregido: se retira "musician" y se añade
-- engineer (fue ingeniero de sonido, documentado por Acento). genres ampliado con rock.

UPDATE artists SET second_last_name = 'Bazán',
       occupations = '["engineer"]'::jsonb, genres = ARRAY['rock']::text[]
       WHERE slug = 'roger-zayas-bazan';

